const walk=(o,d)=>{ if(d>1) return Object.keys(o); return Object.fromEntries(Object.entries(o).map(([k,v])=>[k, v!=null&&typeof v==="object"?walk(v,d+1):v])); };
console.log(JSON.stringify(walk(j,0),null,0).slice(0,3000));'

